css:
.devmgr-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2438;
    background: linear-gradient(168deg, #faf6ef 0%, #f3eee6 55%, #ece6f0 100%);
    border-radius: 18px;
}

.devmgr-container * {
    box-sizing: border-box;
}

.devmgr-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #3b2d63 0%, #5a3b7a 52%, #7c4b6b 100%);
    color: #f7f2ee;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(59, 45, 99, 0.32);
}

.devmgr-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.devmgr-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f6c66b;
    background: rgba(246, 198, 107, 0.14);
    border: 1px solid rgba(246, 198, 107, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.devmgr-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7dcec;
}

.devmgr-program {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.devmgr-prog-card {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(43, 36, 56, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.devmgr-prog-cmdc { border-left: 5px solid #5a3b7a; }
.devmgr-prog-aurora { border-left: 5px solid #c98a1e; }

.devmgr-prog-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #3b2d63;
}

.devmgr-prog-aurora .devmgr-prog-name { color: #b0760f; }

.devmgr-prog-meta {
    font-size: 0.82rem;
    color: #6a607a;
    line-height: 1.4;
}

.devmgr-prog-vs {
    align-self: center;
    font-size: 1.6rem;
    font-weight: 800;
    color: #7c4b6b;
}

.devmgr-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #54485f;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.devmgr-period-counter #currentDay,
.devmgr-period-counter #maxPeriods {
    font-weight: 800;
    color: #7c4b6b;
}

.devmgr-round-name {
    background: rgba(124, 75, 107, 0.14);
    color: #6e4060;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.devmgr-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b0760f;
    background: rgba(201, 138, 30, 0.14);
    border: 1px solid rgba(201, 138, 30, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.devmgr-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.devmgr-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(43, 36, 56, 0.08);
    border-top: 4px solid #5a3b7a;
}

.devmgr-card-transfer { border-top-color: #2f8f74; }
.devmgr-card-completion { border-top-color: #3b6fb0; }
.devmgr-card-sponsor { border-top-color: #c98a1e; }
.devmgr-card-time { border-top-color: #7c4b6b; }

.devmgr-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6f88;
}

.devmgr-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3b2d63;
    font-variant-numeric: tabular-nums;
}

.devmgr-card-transfer .devmgr-value { color: #2f8f74; }
.devmgr-card-completion .devmgr-value { color: #3b6fb0; }
.devmgr-card-sponsor .devmgr-value { color: #b0760f; }
.devmgr-card-time .devmgr-value { color: #7c4b6b; }

.devmgr-sublabel {
    font-size: 0.76rem;
    color: #877d95;
    line-height: 1.35;
}

/* Flagship metric — transfer — gets the loudest story colours. */
.devmgr-card-transfer.devmgr-transfer-danger { border-top-color: #cf4040; }
.devmgr-card-transfer.devmgr-transfer-danger .devmgr-value { color: #cf4040; }
.devmgr-card-transfer.devmgr-transfer-good { border-top-color: #2f8f74; }
.devmgr-card-transfer.devmgr-transfer-good .devmgr-value { color: #2f8f74; }

.devmgr-card-completion.devmgr-completion-danger { border-top-color: #cf4040; }
.devmgr-card-completion.devmgr-completion-danger .devmgr-value { color: #cf4040; }

.devmgr-card-time.devmgr-time-over { border-top-color: #cf4040; }
.devmgr-card-time.devmgr-time-over .devmgr-value { color: #cf4040; }

.devmgr-blend-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e6dfe8;
    color: #54485f;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.devmgr-blend-bar #blendDisplay {
    font-size: 1.02rem;
    letter-spacing: 0.2px;
    color: #cf4040;
    font-weight: 800;
}

.devmgr-blend-bar.devmgr-blend-good #blendDisplay { color: #2f8f74; }
.devmgr-blend-bar.devmgr-blend-mid #blendDisplay { color: #c98a1e; }

.devmgr-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #5a3b7a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(43, 36, 56, 0.07);
}

.devmgr-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.devmgr-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #3b2d63;
    margin-bottom: 6px;
}

.devmgr-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #463c54;
}

.devmgr-briefing-text strong { color: #5a3b7a; }
.devmgr-briefing-text em { color: #b0760f; font-style: italic; }

.devmgr-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(43, 36, 56, 0.07);
}

.devmgr-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #3b2d63;
    border-bottom: 2px solid #ece5ef;
    padding-bottom: 8px;
}

.devmgr-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #382f47;
    margin: 14px 0 6px;
}

.devmgr-container select,
.devmgr-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d3cad8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #2b2438;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.devmgr-container select:focus,
.devmgr-container input[type="number"]:focus {
    outline: none;
    border-color: #7c4b6b;
    box-shadow: 0 0 0 3px rgba(124, 75, 107, 0.16);
}

.devmgr-container select option {
    background-color: #ffffff;
    color: #2b2438;
}

.devmgr-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #7c4b6b;
}

.devmgr-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #54485f;
    margin-top: 4px;
}

.devmgr-range-readout span:nth-child(2) {
    color: #7c4b6b;
    font-weight: 800;
}

.devmgr-hint {
    font-size: 0.8rem;
    color: #877d95;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.devmgr-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.devmgr-container .btn-primary {
    background: linear-gradient(135deg, #5a3b7a 0%, #7c4b6b 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(90, 59, 122, 0.32);
}

.devmgr-container .btn-primary:hover {
    filter: brightness(1.08);
}

.devmgr-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d3cad8;
    color: #6a607a;
    background: transparent;
}

.devmgr-coach {
    background: linear-gradient(160deg, #3b2d63 0%, #4a3470 100%);
    color: #ece2f0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(59, 45, 99, 0.26);
}

.devmgr-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f6c66b;
    margin-bottom: 8px;
}

.devmgr-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.devmgr-coach-body strong { color: #9ad9c6; }
.devmgr-coach-body em { color: #f6c66b; font-style: italic; }

.devmgr-history,
.devmgr-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(43, 36, 56, 0.07);
}

.devmgr-history h3,
.devmgr-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #3b2d63;
}

.devmgr-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #463c54;
}

.devmgr-container table#usfHistoryTable th {
    background: #f1ebf3;
    color: #5a3b7a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d6e4;
}

.devmgr-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eaf2;
    color: #463c54;
}

.devmgr-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7fb;
}

.devmgr-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .devmgr-container {
        padding: 14px;
    }
    .devmgr-header h1 {
        font-size: 1.7rem;
    }
    .devmgr-program {
        flex-direction: column;
    }
    .devmgr-prog-vs {
        transform: rotate(90deg);
    }
    .devmgr-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .devmgr-value {
        font-size: 2rem;
    }
    .devmgr-clock {
        margin-left: 0;
    }
    .devmgr-period-counter {
        font-size: 0.88rem;
    }
    .devmgr-blend-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .devmgr-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / sponsor-renewal debrief scorecard (append-only, namespaced) ===== */
.dm-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.dm-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.dm-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.dm-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.dm-cm-score strong { color: #4f9bd9; }
.dm-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.dm-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.dm-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.dm-cm-target.dm-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.dm-cm-target.dm-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.dm-cm-tick { font-weight: 700; }
.dm-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.dm-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.dm-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.dm-cm-metric strong { font-size: 16px; color: #eceff6; }
.dm-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.dm-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .dm-cm-metric { min-width: 70px; } .dm-cm-verdict { font-size: 19px; } }

