(function() {
    'use strict';

    class DevelopManagersAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Develop the Managers`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Cape Management Development Centre).
            this.START_TRANSFER = 38;     // transfer-to-job rate (%)
            this.START_COMPLETION = 88;   // academic completion rate (%)
            this.START_SPONSOR = 4.6;     // Aurora satisfaction (/10)
            this.START_BLEND = 70;        // % classroom (inverts 70-20-10)
            this.TIME_BUDGET = 6;         // ~6 learner-hours/week
            this.AURORA_REVENUE = 18;     // R18M (~19% of revenue)
            this.AT_RISK_REVENUE = 30;    // R30M+ at risk incl. reputational cascade
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    transfer: this.START_TRANSFER,       // transfer-to-job rate (%)
                    completion: this.START_COMPLETION,   // academic completion rate (%)
                    sponsor: this.START_SPONSOR,         // Aurora satisfaction (/10)
                    timeUsed: 0,                         // learner hours/week the design consumes
                    blendClassroom: this.START_BLEND,    // % of blend that is classroom
                    gapLed: false,                       // designed backward from capability gaps
                    integrated: false,                   // academic + workplace genuinely integrate
                    managerEngaged: false,               // line manager engaged as sponsor
                    overbooked: false,                   // time budget exceeded
                    measuresTransfer: false,             // measurement evidences transfer
                    moreClassroomRun: false,             // answered transfer gap with more classroom
                    transferHistory: [this.START_TRANSFER],
                    completionHistory: [this.START_COMPLETION],
                    sponsorHistory: [this.START_SPONSOR],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic COMMON ERRORS so a
                // blind click-through does NOT auto-win.
                state.decisions = {
                    start: `content`,
                    diagnosis: `ability`,
                    lens: `recall`,
                    depth: 30,
                    blend: `classroom`,
                    integration: `parallel`,
                    social: `none`,
                    time: 9,
                    sequence: `frontload`,
                    manager: `ignore`,
                    gate: `exam`,
                    touch: `0`,
                    measure: `completion`,
                    protect: `drop`,
                    pitch: `rigour`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const st = document.getElementById(`startInput`);
                const di = document.getElementById(`diagnosisInput`);
                const le = document.getElementById(`lensInput`);
                const de = document.getElementById(`depthInput`);
                if (st) decisions.start = st.value;
                if (di) decisions.diagnosis = di.value;
                if (le) decisions.lens = le.value;
                if (de) decisions.depth = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 2) {
                const bl = document.getElementById(`blendInput`);
                const ig = document.getElementById(`integrationInput`);
                const so = document.getElementById(`socialInput`);
                const ti = document.getElementById(`timeInput`);
                if (bl) decisions.blend = bl.value;
                if (ig) decisions.integration = ig.value;
                if (so) decisions.social = so.value;
                if (ti) decisions.time = parseInt(ti.value, 10);
                if (!Number.isFinite(decisions.time) || decisions.time < 1 || decisions.time > 20) {
                    warn(`warn_time_range`); return false;
                }
            } else if (round === 3) {
                const se = document.getElementById(`sequenceInput`);
                const ma = document.getElementById(`managerInput`);
                const ga = document.getElementById(`gateInput`);
                const to = document.getElementById(`touchInput`);
                if (se) decisions.sequence = se.value;
                if (ma) decisions.manager = ma.value;
                if (ga) decisions.gate = ga.value;
                if (to) decisions.touch = to.value;
                if (!decisions.sequence) { warn(`warn_sequence`); return false; }
            } else if (round === 4) {
                const me = document.getElementById(`measureInput`);
                const pr = document.getElementById(`protectInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (me) decisions.measure = me.value;
                if (pr) decisions.protect = pr.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let transferDelta = 0, completionDelta = 0, sponsorDelta = 0, blendDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the capability gaps — gap-led vs content-led (Common Errors 1 & 2).
                switch (d.start) {
                    case `gapmap`: ds.gapLed = true; transferDelta += 5; sponsorDelta += 0.6; coachKey = `coach_r1_gapmap`; break;
                    case `content`: transferDelta -= 2; coachKey = `coach_r1_content`; break;
                    case `addmodules`: ds.moreClassroomRun = true; transferDelta -= 4; blendDelta += 8; sponsorDelta -= 0.4; coachKey = `coach_r1_addmodules`; break;
                }

                switch (d.diagnosis) {
                    case `system`: transferDelta += 4; if (d.start === `gapmap`) coachKey = `coach_r1_sharp`; break;
                    case `ability`: transferDelta -= 2; coachKey = `coach_r1_ability`; break;
                    case `motivation`: transferDelta -= 1; completionDelta -= 2; coachKey = `coach_r1_motivation`; break;
                }

                switch (d.lens) {
                    case `systems`: transferDelta += 3; sponsorDelta += 0.4; break;
                    case `fixed`: transferDelta += 1; break;
                    case `recall`: transferDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_recall` : coachKey; break;
                }

                // Depth of gap-to-outcome mapping (the deliverable's quality).
                if (d.depth >= 70) { transferDelta += 3; sponsorDelta += 0.5; }
                else if (d.depth <= 25) { transferDelta -= 2; sponsorDelta -= 0.3; }

                summaryKey = (d.start === `gapmap` && d.diagnosis === `system` && d.lens === `systems`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Blend the learning — the 70-20-10 lever (Common Errors 1 & 3).
                switch (d.blend) {
                    case `balanced`: ds.blendClassroom = 50; transferDelta += 9; sponsorDelta += 0.6; coachKey = `coach_r2_balanced`; break;
                    case `classroom`: ds.blendClassroom = 70; transferDelta -= 2; coachKey = `coach_r2_classroom`; break;
                    case `more_class`: ds.blendClassroom = 80; ds.moreClassroomRun = true; transferDelta -= 7; sponsorDelta -= 0.7; coachKey = `coach_r2_moreclass`; break;
                    case `all_job`: ds.blendClassroom = 10; transferDelta += 2; completionDelta -= 8; sponsorDelta -= 0.3; coachKey = `coach_r2_alljob`; break;
                }

                // Integration of the two halves (Common Error 3 — Shelley's core).
                switch (d.integration) {
                    case `integrated`: ds.integrated = true; transferDelta += 8; sponsorDelta += 0.5; break;
                    case `parallel`: transferDelta -= 4; coachKey = `coach_r2_parallel`; break;
                    case `sequential`: transferDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_sequential` : coachKey; break;
                }

                // The "20" — social / coaching / reflection.
                switch (d.social) {
                    case `built_in`: transferDelta += 4; sponsorDelta += 0.3; break;
                    case `optional`: transferDelta += 1; break;
                    case `none`: transferDelta -= 2; break;
                }

                // Learner-time budget (Common Error 6 — overload).
                ds.timeUsed = d.time;
                if (d.time > this.TIME_BUDGET) {
                    ds.overbooked = true;
                    const over = d.time - this.TIME_BUDGET;
                    completionDelta -= Math.min(18, over * 3);     // the pathway won't all happen
                    transferDelta -= Math.min(10, over * 2);
                    coachKey = `coach_r2_overbook`;
                } else {
                    ds.overbooked = false;
                    if (d.time >= 5) { sponsorDelta += 0.2; }       // a realistic, full-but-feasible design
                }

                summaryKey = (d.blend === `balanced` && d.integration === `integrated` && !ds.overbooked) ? `sum_r2_good` :
                             (ds.overbooked ? `sum_r2_overbook` :
                             (d.blend === `more_class` ? `sum_r2_moreclass` : `sum_r2_weak`));
            } else if (round === 3) {
                // Sequence the pathway & engage the workplace (Common Errors 4 & 5).
                switch (d.sequence) {
                    case `spiral`: transferDelta += 7; sponsorDelta += 0.4; break;
                    case `frontload`: transferDelta -= 3; coachKey = `coach_r3_frontload`; break;
                    case `blocks`: transferDelta -= 1; break;
                }

                // The line manager (Common Error 4 — workplace conditions).
                switch (d.manager) {
                    case `engage`: ds.managerEngaged = true; transferDelta += 8; sponsorDelta += 1.0; break;
                    case `inform`: transferDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_inform` : coachKey; break;
                    case `ignore`: transferDelta -= 5; sponsorDelta -= 0.5; coachKey = `coach_r3_ignoremgr`; break;
                }

                // Stage gates — assessment aligned to transfer (Common Error 5).
                switch (d.gate) {
                    case `deliverable`: transferDelta += 6; completionDelta += 2; sponsorDelta += 0.5; break;
                    case `exam`: transferDelta -= 3; completionDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_exam` : coachKey; break;
                    case `attendance`: transferDelta -= 1; completionDelta += 1; break;
                }

                // Learner–manager touchpoints reinforce engagement.
                const touch = parseInt(d.touch, 10) || 0;
                if (touch >= 4) { transferDelta += 3; sponsorDelta += 0.3; }
                else if (touch === 0) { transferDelta -= 2; }

                if (d.sequence === `spiral` && d.manager === `engage` && d.gate === `deliverable`) {
                    coachKey = `coach_r3_pathway`;
                }

                summaryKey = (d.sequence === `spiral` && d.manager === `engage` && d.gate === `deliverable`) ? `sum_r3_good` :
                             (d.manager === `ignore` ? `sum_r3_nomgr` :
                             (d.gate === `exam` ? `sum_r3_recall` : `sum_r3_weak`));
            } else if (round === 4) {
                // Evidence the uplift & win back the sponsor.
                switch (d.measure) {
                    case `transfer`: ds.measuresTransfer = true; transferDelta += 4; sponsorDelta += 1.2; break;
                    case `self`: transferDelta += 1; sponsorDelta += 0.2; coachKey = `coach_r4_self`; break;
                    case `completion`: sponsorDelta -= 0.6; coachKey = `coach_r4_completiononly`; break;
                }

                // Protect completion while chasing transfer.
                switch (d.protect) {
                    case `align`: completionDelta += 4; transferDelta += 4; sponsorDelta += 0.5; break;
                    case `harden`: completionDelta -= 10; coachKey = `coach_r4_harden`; break;
                    case `drop`: completionDelta -= 6; sponsorDelta -= 0.2; coachKey = `coach_r4_drop`; break;
                }

                // The renewal pitch to Aurora's CHRO.
                switch (d.pitch) {
                    case `value`: sponsorDelta += 1.4; transferDelta += 2; if (d.measure === `transfer`) coachKey = `coach_r4_value`; break;
                    case `rigour`: sponsorDelta -= 0.4; coachKey = (coachKey === `coach_default`) ? `coach_r4_rigour` : coachKey; break;
                    case `discount`: sponsorDelta -= 0.8; coachKey = `coach_r4_discount`; break;
                }

                if (d.conviction >= 60) { sponsorDelta += 0.3; transferDelta += 2; }
                else if (d.conviction <= 25) { sponsorDelta -= 0.3; }

                summaryKey = (d.measure === `transfer` && d.protect === `align` && d.pitch === `value`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.transfer = Math.max(0, Math.min(100, Math.round((ds.transfer + transferDelta) * 10) / 10));
            ds.completion = Math.max(0, Math.min(100, Math.round((ds.completion + completionDelta) * 10) / 10));
            ds.sponsor = Math.max(0, Math.min(10, Math.round((ds.sponsor + sponsorDelta) * 10) / 10));
            if (round === 1 && blendDelta) {
                ds.blendClassroom = Math.max(0, Math.min(100, ds.blendClassroom + blendDelta));
            }

            // ---- Sponsor confidence is also DERIVED from whether transfer is
            // genuinely closing the gap, not just from the pitch. ----
            const gapClosed = (ds.transfer - this.START_TRANSFER);   // points of transfer gained
            if (gapClosed >= 25 && ds.completion >= 80) {
                ds.sponsor = Math.min(10, Math.round((ds.sponsor + 0.4) * 10) / 10);
            } else if (gapClosed <= 0) {
                ds.sponsor = Math.max(0, Math.round((ds.sponsor - 0.3) * 10) / 10);
            }

            ds.transferHistory.push(ds.transfer);
            ds.completionHistory.push(ds.completion);
            ds.sponsorHistory.push(ds.sponsor);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                transfer: ds.transfer,
                transferDelta: Math.round(transferDelta * 10) / 10,
                completion: ds.completion,
                completionDelta: Math.round(completionDelta * 10) / 10,
                sponsor: ds.sponsor,
                sponsorDelta: Math.round(sponsorDelta * 10) / 10,
                blendClassroom: ds.blendClassroom,
                timeUsed: ds.timeUsed,
                overbooked: ds.overbooked,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

