        _composite(ds) {
            // v1.1.0 - verbatim replica of the getPerformanceSummary composite (weights unchanged).
            const transfer = Math.round(ds.transfer);
            const completion = Math.round(ds.completion);
            const sponsor = Math.round(ds.sponsor * 10) / 10;
            const gapClosed = transfer - this.START_TRANSFER;
            return Math.round(transfer * 0.42 + completion * 0.20 + (sponsor * 10) * 0.28 + Math.max(0, Math.min(100, gapClosed * 2)) * 0.10);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized sponsor-renewal debrief scorecard (was: framework default that
            // discarded score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="dm-cm-target ' + (ok ? 'dm-cm-met' : 'dm-cm-missed') + '">'
                    + '<span class="dm-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.transferred, t('tgt_transfer'))
                + chip(!!summary.completionHeld, t('tgt_completion'))
                + chip(!!summary.sponsorWon, t('tgt_sponsor'))
                + chip(!!summary.integrated, t('tgt_integrated'));
            const metric = function (label, val) {
                return '<div class="dm-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_transfer'), nz(summary.transfer) + '%')
                + metric(t('kpi_completion'), nz(summary.completion) + '%')
                + metric(t('kpi_sponsor'), nz(summary.sponsor) + '/10')
                + metric(t('kpi_gap'), nz(summary.gapClosed) + ' pts');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="dm-cm">'
                +   '<div class="dm-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="dm-cm-verdict">' + verdict + '</div>'
                +   '<div class="dm-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="dm-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="dm-cm-targets">' + targets + '</div>'
                +   '<div class="dm-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="dm-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const transfer = Math.round(ds.transfer);
            const completion = Math.round(ds.completion);
            const sponsor = Math.round(ds.sponsor * 10) / 10;

            const transferred = transfer >= 65;
            const completionHeld = completion >= 80;
            const sponsorWon = sponsor >= 7;
            const gapClosed = transfer - this.START_TRANSFER;

            // Composite: transfer is the flagship and weighted heaviest.
            const composite = Math.round(
                transfer * 0.42 + completion * 0.20 + (sponsor * 10) * 0.28 + Math.max(0, Math.min(100, gapClosed * 2)) * 0.10
            );

            let pattern = `mixed`;
            if (ds.moreClassroomRun && !ds.integrated) pattern = `more_classroom`;
            else if (!ds.gapLed && transfer < 50) pattern = `content_led`;
            else if (ds.overbooked && completion < 80) pattern = `overbooked`;
            else if (transferred && ds.integrated && ds.managerEngaged) pattern = `integrated`;
            else pattern = `mixed`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_walks`;
            if (transferred && completionHeld && sponsorWon && composite >= 72) perfKey = `grade_renewed`;
            else if (transferred && completionHeld && pattern !== `more_classroom`) perfKey = `grade_lifted`;
            else if (ds.moreClassroomRun && !transferred) perfKey = `grade_classroom`;
            else if (ds.overbooked && completion < 80) perfKey = `grade_overbooked`;
            else if (composite >= 52) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (transferred && completionHeld && sponsorWon && ds.integrated) insights.push(window.mySimulation.t(`insight_integrated`));
            else if (pattern === `more_classroom`) insights.push(window.mySimulation.t(`insight_more_classroom`));
            else if (pattern === `content_led`) insights.push(window.mySimulation.t(`insight_content_led`));
            else if (pattern === `overbooked`) insights.push(window.mySimulation.t(`insight_overbooked`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!ds.gapLed) insights.push(window.mySimulation.t(`insight_no_gapmap`));
            if (!ds.integrated) insights.push(window.mySimulation.t(`insight_no_integration`));
            if (!ds.managerEngaged) insights.push(window.mySimulation.t(`insight_no_manager`));
            if (!ds.measuresTransfer) insights.push(window.mySimulation.t(`insight_no_measure`));
            if (completion < 75) insights.push(window.mySimulation.t(`insight_completion_lost`));

            return {
                gradeKey: perfKey,
                score: composite,
                integrated: !!ds.integrated,
                transfer: transfer,
                completion: completion,
                sponsor: sponsor,
                gapClosed: gapClosed,
                transferred: transferred,
                completionHeld: completionHeld,
                sponsorWon: sponsorWon,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

