            if (!ds.integrated && state.currentPeriod >= 2) return window.mySimulation.t(`hint_integrate`);
            if (!ds.managerEngaged && state.currentPeriod >= 3) return window.mySimulation.t(`hint_manager`);
            if (ds.transfer >= 60 && ds.completion >= 80 && ds.sponsor >= 7) return window.mySimulation.t(`hint_strong`);
            return null;
        }

